t = int(input())
for _ in range(t):
	(n, s) = map(int, input().split())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	visited = [0] * (n + 1)
	m = 1
	empty = []
	for (a_i, b_i) in zip(a, b):
		if b_i != -1 and a_i - b_i > s:
			m = 0
			break
		elif b_i == -1:
			empty.append(a_i)
		else:
			visited[b_i] += 1
	else:
		missing = [i for i in range(1, n + 1) if visited[i] == 0]
		empty.sort()
		l_max = len(missing)
		e_hi = 0
		for (e_lo, m_i) in enumerate(missing):
			while e_hi != l_max and m_i + s >= empty[e_hi]:
				e_hi += 1
			m = m * max(0, e_hi - e_lo) % 998244353
	print(m)
